sealed class CryptoException: kotlin.Exception() {
    
    class KeyDerivation(
        
        val v1: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Encryption(
        
        val v1: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Decryption(
        
        val v1: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class InvalidKeyLength(
        
        val `expected`: kotlin.ULong, 
        
        val `actual`: kotlin.ULong
        ) : CryptoException() {
        override val message
            get() = "expected=${ `expected` }, actual=${ `actual` }"
    }
    
    class InvalidIvLength(
        
        val `expected`: kotlin.ULong, 
        
        val `actual`: kotlin.ULong
        ) : CryptoException() {
        override val message
            get() = "expected=${ `expected` }, actual=${ `actual` }"
    }
    
    class Rsa(
        
        val v1: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class InvalidPem(
        
        val v1: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class InvalidSecretKey(
        ) : CryptoException() {
        override val message
            get() = ""
    }
    
    class Base64Decode(
        
        val v1: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class HexDecode(
        
        val v1: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Srp(
        
        val v1: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class InvalidPublicEphemeral(
        ) : CryptoException() {
        override val message
            get() = ""
    }
    
    class InvalidSessionProof(
        ) : CryptoException() {
        override val message
            get() = ""
    }
    
    class Utf8(
        
        val v1: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class InvalidInput(
        
        val v1: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class KeyDestroyed(
        ) : CryptoException() {
        override val message
            get() = ""
    }
    
    class KeyHandleUnavailable(
        ) : CryptoException() {
        override val message
            get() = ""
    }
    
    class BackgroundTaskFailed(
        ) : CryptoException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CryptoException> {
        override fun lift(error_buf: RustBuffer.ByValue): CryptoException = FfiConverterTypeCryptoError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCryptoError : FfiConverterRustBuffer<CryptoException> {
    override fun read(buf: ByteBuffer): CryptoException {
        

        return when(buf.getInt()) {
            1 -> CryptoException.KeyDerivation(
                FfiConverterString.read(buf),
                )
            2 -> CryptoException.Encryption(
                FfiConverterString.read(buf),
                )
            3 -> CryptoException.Decryption(
                FfiConverterString.read(buf),
                )
            4 -> CryptoException.InvalidKeyLength(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            5 -> CryptoException.InvalidIvLength(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            6 -> CryptoException.Rsa(
                FfiConverterString.read(buf),
                )
            7 -> CryptoException.InvalidPem(
                FfiConverterString.read(buf),
                )
            8 -> CryptoException.InvalidSecretKey()
            9 -> CryptoException.Base64Decode(
                FfiConverterString.read(buf),
                )
            10 -> CryptoException.HexDecode(
                FfiConverterString.read(buf),
                )
            11 -> CryptoException.Srp(
                FfiConverterString.read(buf),
                )
            12 -> CryptoException.InvalidPublicEphemeral()
            13 -> CryptoException.InvalidSessionProof()
            14 -> CryptoException.Utf8(
                FfiConverterString.read(buf),
                )
            15 -> CryptoException.InvalidInput(
                FfiConverterString.read(buf),
                )
            16 -> CryptoException.KeyDestroyed()
            17 -> CryptoException.KeyHandleUnavailable()
            18 -> CryptoException.BackgroundTaskFailed()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CryptoException): ULong {
        return when(value) {
            is CryptoException.KeyDerivation -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CryptoException.Encryption -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CryptoException.Decryption -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CryptoException.InvalidKeyLength -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`expected`)
                + FfiConverterULong.allocationSize(value.`actual`)
            )
            is CryptoException.InvalidIvLength -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`expected`)
                + FfiConverterULong.allocationSize(value.`actual`)
            )
            is CryptoException.Rsa -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CryptoException.InvalidPem -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CryptoException.InvalidSecretKey -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CryptoException.Base64Decode -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CryptoException.HexDecode -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CryptoException.Srp -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CryptoException.InvalidPublicEphemeral -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CryptoException.InvalidSessionProof -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CryptoException.Utf8 -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CryptoException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CryptoException.KeyDestroyed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CryptoException.KeyHandleUnavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CryptoException.BackgroundTaskFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: CryptoException, buf: ByteBuffer) {
        when(value) {
            is CryptoException.KeyDerivation -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CryptoException.Encryption -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
